/*
 * Evercast's service worker.
 *
 * Handwritten and served verbatim out of `public/`, rather than generated by a
 * plugin, because what it has to do is small and the alternative is a build
 * dependency that rewrites this file on every release.
 *
 * It exists for one reason: Evercast was a browser tab that re-fetched six
 * megabytes of models on every visit, competing with apps that have an icon on
 * the home screen. Nothing here sends anything anywhere - every rule below is
 * same-origin only, which keeps the promise `connect-src 'self'` makes.
 */

/*
 * Bumped by hand when a rule in this file changes, which is the only thing it
 * gates. Content is NOT versioned against it: hashed bundles are immutable and
 * everything else revalidates in the background, so a release does not need
 * anyone to remember this number.
 */
const CACHE = 'evercast-v1';

/** Immutable: Vite writes a content hash into every one of these names. */
const HASHED = /^\/assets\//;

/**
 * Stable paths whose contents can change between releases. Served from cache
 * for speed and refreshed behind the player, so a new model arrives on the
 * next launch without anything having to be versioned by hand.
 */
const REVALIDATE = /^\/(models|fonts|icons)\/|^\/manifest\.webmanifest$/;

self.addEventListener('install', (event) => {
  // The shell, so a cold launch offline has something to open.
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(['/', '/manifest.webmanifest']))
      .then(() => self.skipWaiting())
      .catch(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (response.ok) (await caches.open(CACHE)).put(request, response.clone());
  return response;
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(CACHE);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    // Offline with nothing cached is a genuine failure; offline with a cached
    // copy already returned is not, and must not become an unhandled rejection.
    .catch(() => cached);
  return cached ?? network;
}

/**
 * Network first, because the shell carries the script tags that name the
 * hashed bundles - serving a stale one would pin the player to an old build
 * whose assets may already have been evicted.
 */
async function shellFirst(request) {
  try {
    const response = await fetch(request);
    if (response.ok) (await caches.open(CACHE)).put('/', response.clone());
    return response;
  } catch (error) {
    const cached = await caches.match('/');
    if (cached) return cached;
    throw error;
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  // Same-origin only. Evercast makes no cross-origin requests, and a worker
  // that cached one would be the first thing here to break that.
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(shellFirst(request));
    return;
  }
  if (HASHED.test(url.pathname)) {
    event.respondWith(cacheFirst(request));
    return;
  }
  if (REVALIDATE.test(url.pathname)) {
    event.respondWith(staleWhileRevalidate(request));
  }
});
